  ('P2', 'workhub_private.p2_installs', ARRAY['P2-01','P2-02']),
  ('P3', 'workhub_private.p3_installs', ARRAY['P3-01','P3-02']),
  ('P4', 'workhub_private.p4_installs', ARRAY['P4-01','P4-02']),
  ('P5', 'workhub_private.p5_installs', ARRAY['P5-01','P5-02']),
  ('P6', 'workhub_private.p6_installs', ARRAY['P6-01','P6-02']),
  ('P7', 'workhub_private.p7_installs', ARRAY['P7-01','P7-02']),
  ('P7-05', 'workhub_private.p7_installs', ARRAY['P7-05']),
  ('P8-01', 'workhub_private.p8_installs', ARRAY['P8-01']),
  ('P8-02', 'workhub_private.p8_installs', ARRAY['P8-02']),
  ('P8-03', 'workhub_private.p8_installs', ARRAY['P8-03']),
  ('P8-04', 'workhub_private.p8_installs', ARRAY['P8-04']),
  ('T1-01', 'workhub_private.t1_installs', ARRAY['T1-01']),
  ('T1-02', 'workhub_private.t1_installs', ARRAY['T1-02']),
  ('T1-03', 'workhub_private.t1_installs', ARRAY['T1-03']),
  ('T1-07', 'workhub_private.t1_installs', ARRAY['T1-07']),
  ('T2-01', 'workhub_private.t2_installs', ARRAY['T2-01']),
  ('T2-02', 'workhub_private.t2_installs', ARRAY['T2-02']),
  ('T2-03', 'workhub_private.t2_installs', ARRAY['T2-03']),
  ('T2-04', 'workhub_private.t2_installs', ARRAY['T2-04']),
  ('T2-05', 'workhub_private.t2_installs', ARRAY['T2-05']),
  ('T2-06', 'workhub_private.t2_installs', ARRAY['T2-06']),
  ('P9-01', 'workhub_private.p9_installs', ARRAY['P9-01']),
  ('P9-02', 'workhub_private.p9_installs', ARRAY['P9-02']),
  ('P10-01', 'workhub_private.p10_installs', ARRAY['P10-01']),
  ('P10-02', 'workhub_private.p10_installs', ARRAY['P10-02']),
  ('T3-01', 'workhub_private.t3_installs', ARRAY['T3-01']),
  ('T3-02', 'workhub_private.t3_installs', ARRAY['T3-02']),
  ('T3-03', 'workhub_private.t3_installs', ARRAY['T3-03']),
  ('T4-01', 'workhub_private.t4_installs', ARRAY['T4-01']),
  ('P10-AI-01', 'workhub_private.p10_ai_installs', ARRAY['P10-AI-01']),
  ('P10-AI-02', 'workhub_private.p10_ai_installs', ARRAY['P10-AI-02']),
  ('P10-AI-03', 'workhub_private.p10_ai_installs', ARRAY['P10-AI-03']),
  ('P10-AI-09', 'workhub_private.p10_ai_installs', ARRAY['P10-AI-09']),
  ('P10-AI-10', 'workhub_private.p10_ai_installs', ARRAY['P10-AI-10']),
  ('K1', NULL, ARRAY['K1']),
  ('M1-01', 'workhub_private.m1_installs', ARRAY['M1-01']),
  ('MP1-01', 'workhub_private.mp1_installs', ARRAY['MP1-01'])
),
-- 함수 소유자 허용표: 단계 SQL 을 실행한 승인된 설치 역할. Supabase SQL Editor 는 postgres 로 실행한다.
-- "가장 많은 소유자"와 비교하지 않는다 — 전부가 한꺼번에 다른 역할로 바뀌면 그 역할이 기준이 되어 놓치기 때문.
-- 운영 기준선(통합_실행안내 0-1)에서 다른 역할이 나오면 여기 값을 고치지 말고 멈춘 뒤 원인부터 확인한다.
own(role) AS (VALUES ('postgres')),
st AS (
  SELECT s.stage, s.ord, s.deps,
         CASE WHEN s.stage = 'R0' THEN (to_regclass('workhub.schools') IS NOT NULL)::int + (to_regclass('workhub.tasks') IS NOT NULL)::int
              WHEN s.stage = 'K1' THEN (to_regprocedure('public.workhub_knowledge_get(text,text,integer)') IS NOT NULL)::int + (to_regprocedure('public.workhub_knowledge_history(text,text,integer)') IS NOT NULL)::int
              WHEN to_regclass(rec.tbl) IS NULL THEN 0
              ELSE (xpath('/row/n/text()', query_to_xml(format('SELECT count(*) AS n FROM %s WHERE batch = ANY (%L)', rec.tbl, rec.batches), false, true, '')))[1]::text::int
         END AS n,
         CASE WHEN s.stage IN ('R0','K1') THEN 2 ELSE cardinality(rec.batches) END AS total
    FROM s LEFT JOIN rec ON rec.stage = s.stage
),
inst AS (SELECT stage, ord, deps, n = total AS installed, n > 0 AND n < total AS partial FROM st),
exp AS (
  SELECT DISTINCT ON (m.kind, m.key) m.kind, m.key, m.attrs::jsonb AS attrs, m.stage
    FROM m JOIN inst i ON i.stage = m.stage AND i.installed
   ORDER BY m.kind, m.key, i.ord DESC
),
want AS (SELECT kind, key, attrs, stage FROM exp WHERE attrs IS NOT NULL),
got AS (
SELECT 'function' AS kind, n.nspname || '.' || p.proname || '(' || pg_get_function_identity_arguments(p.oid) || ')' AS key,
         jsonb_build_object('result', pg_get_function_result(p.oid), 'lang', l.lanname, 'secdef', p.prosecdef,
           'config', COALESCE(array_to_string(p.proconfig, ' '), ''),
           'exec', COALESCE((SELECT string_agg(g, ' ' ORDER BY g) FROM (SELECT DISTINCT CASE WHEN a.grantee = 0 THEN 'PUBLIC' ELSE r.rolname END AS g
                      FROM aclexplode(COALESCE(p.proacl, acldefault('f', p.proowner))) a LEFT JOIN pg_roles r ON r.oid = a.grantee
                     WHERE a.privilege_type = 'EXECUTE' AND (a.grantee = 0 OR r.rolname IN ('anon','authenticated','service_role'))) x), ''),
           'eff', COALESCE((SELECT string_agg(r.rolname, ' ' ORDER BY r.rolname) FROM pg_roles r
                     WHERE r.rolname IN ('anon','authenticated','service_role') AND has_function_privilege(r.oid, p.oid, 'EXECUTE')), ''),
           'body', md5(replace(p.prosrc, chr(13), ''))) AS attrs,
         (SELECT rolname FROM pg_roles WHERE oid = p.proowner)::text AS owner
    FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace JOIN pg_language l ON l.oid = p.prolang
   WHERE n.nspname IN ('workhub','workhub_private','workhub_storage') OR (n.nspname = 'public' AND p.proname LIKE 'workhub\_%')
  UNION ALL
  SELECT 'trigger', c.relnamespace::regnamespace::text || '.' || c.relname || '.' || t.tgname,
         jsonb_build_object('def', md5(pg_get_triggerdef(t.oid)), 'enabled', t.tgenabled::text), NULL
    FROM pg_trigger t JOIN pg_class c ON c.oid = t.tgrelid JOIN pg_proc f ON f.oid = t.tgfoid
   WHERE NOT t.tgisinternal AND (c.relnamespace::regnamespace::text IN ('workhub','workhub_private','workhub_storage')
                                 OR f.pronamespace::regnamespace::text IN ('workhub','workhub_private','workhub_storage'))
  UNION ALL
  SELECT 'constraint', c.relnamespace::regnamespace::text || '.' || c.relname || '.' || k.conname,
         jsonb_build_object('def', md5(pg_get_constraintdef(k.oid))), NULL
    FROM pg_constraint k JOIN pg_class c ON c.oid = k.conrelid
   WHERE c.relnamespace::regnamespace::text IN ('workhub','workhub_private','workhub_storage')
  UNION ALL
  SELECT 'policy', schemaname || '.' || tablename || '.' || policyname,
         jsonb_build_object('def', md5(concat_ws('|', permissive, roles::text, cmd, qual, with_check))), NULL
    FROM pg_policies WHERE policyname LIKE 'workhub%' OR schemaname IN ('workhub','workhub_private','workhub_storage')
 UNION ALL
 SELECT 'table',n.nspname||'.'||c.relname,
  jsonb_build_object('kind',c.relkind,'persistence',c.relpersistence,'rls',c.relrowsecurity,'forceRls',c.relforcerowsecurity,
    'owner',pg_get_userbyid(c.relowner),
    'api',coalesce((SELECT string_agg(r.role||':'||p.privilege,' ' ORDER BY r.role,p.privilege)
      FROM unnest(ARRAY['anon','authenticated','service_role']) r(role)
      CROSS JOIN unnest(ARRAY['SELECT','INSERT','UPDATE','DELETE','TRUNCATE','REFERENCES','TRIGGER']) p(privilege)
      WHERE has_table_privilege(r.role,c.oid,p.privilege)),'')),NULL
 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
 WHERE n.nspname IN ('workhub','workhub_private','workhub_storage') AND c.relkind IN ('r','p','v','m')
 UNION ALL
 SELECT 'column',n.nspname||'.'||c.relname||'.'||a.attname,
  jsonb_build_object('position',a.attnum,'type',format_type(a.atttypid,a.atttypmod),'notNull',a.attnotnull,
   'identity',a.attidentity,'generated',a.attgenerated,'default',coalesce(pg_get_expr(d.adbin,d.adrelid),''),
   'api',coalesce((SELECT string_agg(r.role||':'||p.privilege,' ' ORDER BY r.role,p.privilege)
    FROM unnest(ARRAY['anon','authenticated','service_role']) r(role)
    CROSS JOIN unnest(ARRAY['SELECT','INSERT','UPDATE','REFERENCES']) p(privilege)
    WHERE has_column_privilege(r.role,c.oid,a.attnum,p.privilege)),'')),NULL
 FROM pg_attribute a JOIN pg_class c ON c.oid=a.attrelid JOIN pg_namespace n ON n.oid=c.relnamespace
 LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum
 WHERE n.nspname IN ('workhub','workhub_private','workhub_storage') AND c.relkind IN ('r','p','v','m') AND a.attnum>0 AND NOT a.attisdropped
 UNION ALL
 SELECT 'index',n.nspname||'.'||t.relname||'.'||c.relname,
  jsonb_build_object('definition',pg_get_indexdef(c.oid),'valid',i.indisvalid,'ready',i.indisready),NULL
 FROM pg_index i JOIN pg_class c ON c.oid=i.indexrelid JOIN pg_class t ON t.oid=i.indrelid JOIN pg_namespace n ON n.oid=t.relnamespace
 WHERE n.nspname IN ('workhub','workhub_private','workhub_storage')
 UNION ALL
 SELECT 'schema',n.nspname,
  jsonb_build_object('owner',pg_get_userbyid(n.nspowner),'api',coalesce((SELECT string_agg(r.role||':'||p.privilege,' ' ORDER BY r.role,p.privilege)
    FROM unnest(ARRAY['anon','authenticated','service_role']) r(role) CROSS JOIN unnest(ARRAY['USAGE','CREATE']) p(privilege)
    WHERE has_schema_privilege(r.role,n.oid,p.privilege)),'')),NULL
 FROM pg_namespace n WHERE n.nspname IN ('workhub','workhub_private','workhub_storage')
 UNION ALL
 SELECT 'enum',n.nspname||'.'||t.typname,
  jsonb_build_object('values',(SELECT jsonb_agg(e.enumlabel ORDER BY e.enumsortorder) FROM pg_enum e WHERE e.enumtypid=t.oid)),NULL
 FROM pg_type t JOIN pg_namespace n ON n.oid=t.typnamespace WHERE n.nspname IN ('workhub','workhub_private','workhub_storage') AND t.typtype='e'

),
miss AS (SELECT w.kind, w.key FROM want w WHERE NOT EXISTS (SELECT 1 FROM got g WHERE g.kind = w.kind AND g.key = w.key)),
extra AS (SELECT g.kind, g.key FROM got g WHERE NOT EXISTS (SELECT 1 FROM want w WHERE w.kind = g.kind AND w.key = g.key)),
diff AS (SELECT w.kind, w.key, w.attrs AS want, g.attrs AS got FROM want w JOIN got g ON g.kind = w.kind AND g.key = w.key WHERE w.attrs <> g.attrs),
fdiff(item, key, detail) AS (
  SELECT f.item, d.key, (d.want ->> f.field) || ' → ' || (d.got ->> f.field)
    FROM diff d CROSS JOIN (VALUES ('exec', 'exec'), ('exec', 'eff'), ('sec', 'secdef'), ('sec', 'config'), ('sig', 'result'), ('sig', 'lang'), ('body', 'body')) f(item, field)
   WHERE d.kind = 'function' AND (d.want -> f.field) IS DISTINCT FROM (d.got -> f.field)
)
SELECT 'INT-09-01' AS no, '적용된 단계 조합(부분 적용 · 선행 단계 없이 적용 없음)' AS item,
       CASE WHEN bool_or(partial) OR bool_or(installed AND EXISTS (SELECT 1 FROM unnest(string_to_array(deps, ' ')) d
                                                             WHERE NOT (SELECT x.installed FROM inst x WHERE x.stage = d)))
            THEN 'FAIL' ELSE 'ok' END AS status,
       COALESCE(string_agg(stage || CASE WHEN partial THEN '(부분 적용!)' ELSE '' END, ' · ' ORDER BY ord) FILTER (WHERE installed OR partial), '(없음)') AS value
  FROM inst
UNION ALL
SELECT 'INT-09-02', '함수: 이 조합에 있어야 할 함수가 모두 있음',
       CASE WHEN count(*) = 0 THEN 'ok' ELSE 'FAIL' END,
       count(*)::text || COALESCE(' — ' || (SELECT string_agg(key, ', ') FROM (SELECT key FROM miss WHERE kind = 'function' ORDER BY key LIMIT 5) x), '')
  FROM miss WHERE kind = 'function'
UNION ALL
SELECT 'INT-09-03', '함수: 목록에 없는 함수 · 같은 이름 다른 인자(오버로드) 없음',
       CASE WHEN count(*) = 0 THEN 'ok' ELSE 'FAIL' END,
       count(*)::text || COALESCE(' — ' || (SELECT string_agg(key || CASE WHEN EXISTS (SELECT 1 FROM want w WHERE w.kind = 'function'
                                                AND split_part(w.key, '(', 1) = split_part(x.key, '(', 1)) THEN '(오버로드)' ELSE '' END, ', ')
                                            FROM (SELECT key FROM extra WHERE kind = 'function' ORDER BY key LIMIT 5) x), '')
  FROM extra WHERE kind = 'function'
UNION ALL
SELECT 'INT-09-04', '함수: API 역할 실행 권한이 단계 설계와 같음 — 직접 부여(PUBLIC · anon · authenticated · service_role)와 실효 권한(상속 포함, anon · authenticated · service_role)',
       CASE WHEN count(*) = 0 THEN 'ok' ELSE 'FAIL' END,
       count(*)::text || COALESCE(' — ' || (SELECT string_agg(key || ' [' || detail || ']', ', ') FROM (SELECT * FROM fdiff WHERE item = 'exec' ORDER BY key LIMIT 5) x), '')
  FROM fdiff WHERE item = 'exec'
UNION ALL
SELECT 'INT-09-05', '함수: SECURITY DEFINER · search_path 가 단계 설계와 같음',
       CASE WHEN count(*) = 0 THEN 'ok' ELSE 'FAIL' END,
       count(*)::text || COALESCE(' — ' || (SELECT string_agg(key || ' [' || detail || ']', ', ') FROM (SELECT * FROM fdiff WHERE item = 'sec' ORDER BY key LIMIT 5) x), '')
  FROM fdiff WHERE item = 'sec'
UNION ALL
SELECT 'INT-09-06', '함수: 반환형 · 언어가 같음',
       CASE WHEN count(*) = 0 THEN 'ok' ELSE 'FAIL' END,
       count(*)::text || COALESCE(' — ' || (SELECT string_agg(key || ' [' || detail || ']', ', ') FROM (SELECT * FROM fdiff WHERE item = 'sig' ORDER BY key LIMIT 5) x), '')
  FROM fdiff WHERE item = 'sig'
UNION ALL
SELECT 'INT-09-07', '함수: 본문이 적용한 SQL 파일과 같음(손으로 바꾼 함수 없음 · 교체는 그 단계 판)',
       CASE WHEN count(*) = 0 THEN 'ok' ELSE 'FAIL' END,
       count(*)::text || COALESCE(' — ' || (SELECT string_agg(key, ', ') FROM (SELECT key FROM fdiff WHERE item = 'body' ORDER BY key LIMIT 5) x), '')
  FROM fdiff WHERE item = 'body'
UNION ALL
SELECT 'INT-09-08', '함수: 소유자가 승인된 설치 역할(own 표)임 — API 역할 · 다른 역할 소유 없음',
       CASE WHEN count(*) = 0 THEN 'ok' ELSE 'FAIL' END,
       count(*)::text || ' (허용: ' || (SELECT string_agg(role, ' · ' ORDER BY role) FROM own) || ')'
       || COALESCE(' — ' || (SELECT string_agg(key || '(' || owner || ')', ', ') FROM (SELECT key, owner FROM got g2 WHERE g2.kind = 'function'
                                         AND g2.owner NOT IN (SELECT role FROM own) ORDER BY key LIMIT 5) x), '')
  FROM got WHERE kind = 'function' AND owner NOT IN (SELECT role FROM own)
UNION ALL
SELECT 'INT-09-' || k.no, k.label || ': 빠짐 · 목록에 없음 · 정의 다름 없음',
       CASE WHEN COALESCE(a.n, 0) + COALESCE(b.n, 0) + COALESCE(c.n, 0) = 0 THEN 'ok' ELSE 'FAIL' END,
       '빠짐 ' || COALESCE(a.n, 0) || ' · 목록에 없음 ' || COALESCE(b.n, 0) || ' · 다름 ' || COALESCE(c.n, 0)
       || COALESCE(' — ' || NULLIF(concat_ws(', ', a.k, b.k, c.k), ''), '')
  FROM (VALUES ('09', 'trigger', '트리거'), ('10', 'constraint', '제약'), ('11', 'policy', 'Storage · 표 정책'), ('14', 'table', '표 · RLS · 소유자 · 실효 권한'), ('15', 'column', '열 · 기본값 · 실효 권한'), ('16', 'index', '인덱스'), ('17', 'schema', '스키마 · 실효 권한'), ('18', 'enum', '열거형')) k(no, kind, label)
  LEFT JOIN LATERAL (SELECT count(*) AS n, string_agg('빠짐 ' || key, ', ') FILTER (WHERE rn <= 3) AS k
                       FROM (SELECT key, row_number() OVER (ORDER BY key) rn FROM miss WHERE kind = k.kind) x) a ON true
  LEFT JOIN LATERAL (SELECT count(*) AS n, string_agg('추가 ' || key, ', ') FILTER (WHERE rn <= 3) AS k
                       FROM (SELECT key, row_number() OVER (ORDER BY key) rn FROM extra WHERE kind = k.kind) x) b ON true
  LEFT JOIN LATERAL (SELECT count(*) AS n, string_agg('다름 ' || key, ', ') FILTER (WHERE rn <= 3) AS k
                       FROM (SELECT key, row_number() OVER (ORDER BY key) rn FROM diff WHERE kind = k.kind) x) c ON true
UNION ALL
SELECT 'INT-09-12', '점검한 객체 수(이 조합의 목록 기준)', 'info',
       (SELECT string_agg(kind || ' ' || n, ' · ' ORDER BY kind) FROM (SELECT kind, count(*) AS n FROM want GROUP BY kind) x)
UNION ALL
SELECT 'INT-09-13', 'R1-04 의 03 · 04 · 09 행이 FAIL 로 보이는 까닭(정상 여부는 위 02~10 이 정확한 목록으로 판단)', 'info',
       'R1-04-03·04 가 세는 이름(workhub_collection_% · workhub_file_%)의 공개 함수: '
       || COALESCE((SELECT string_agg(stage || ' ' || n, ' · ' ORDER BY ord) FROM (
            SELECT m0.stage, i.ord, count(*) AS n FROM want w
              JOIN LATERAL (SELECT m.stage FROM m WHERE m.kind = 'function' AND m.key = w.key ORDER BY (SELECT ord FROM s WHERE s.stage = m.stage) LIMIT 1) m0 ON true
              JOIN inst i ON i.stage = m0.stage
             WHERE w.kind = 'function' AND (w.key LIKE 'public.workhub\_collection\_%' OR w.key LIKE 'public.workhub\_file\_%')
             GROUP BY m0.stage, i.ord) x), '없음')
       || ' (R1 만이면 17) · R1-04-09 가 보는 작업 목록 CHECK 를 정의 · 바꾼 단계: '
       || COALESCE((SELECT string_agg(m.stage, ' · ') FROM m JOIN inst i ON i.stage = m.stage AND i.installed
                     WHERE m.kind = 'constraint' AND m.key = 'workhub.service_principals.service_principals_action_registry'), '없음')
ORDER BY 1;
